<script setup lang="ts">import{onMounted,reactive,ref}from'vue';import{Plus,Trash2}from'@lucide/vue';import{api,errorMessage}from'../lib/api';const organization=reactive({name:'',type:'',country:'',marketplaceVisible:true}),members=ref<any[]>([]),error=ref(''),saved=ref(''),showAdd=ref(false),invite=reactive({fullName:'',email:'',role:'EMPLOYEE'});async function load(){try{Object.assign(organization,(await api.get('/organization')).data.data);members.value=(await api.get('/organization/members')).data.data}catch(e){error.value=errorMessage(e)}}async function save(){try{await api.patch('/organization',organization);saved.value='Organization settings saved.'}catch(e){error.value=errorMessage(e)}}async function add(){try{await api.post('/organization/members',invite);showAdd.value=false;await load()}catch(e){error.value=errorMessage(e)}}async function role(m:any){try{await api.patch(`/organization/members/${m.id}`,{role:m.role})}catch(e){error.value=errorMessage(e)}}async function remove(m:any){if(!confirm(`Remove ${m.user.fullName}?`))return;try{await api.delete(`/organization/members/${m.id}`);await load()}catch(e){error.value=errorMessage(e)}}onMounted(load)</script>
<template><div class="page-heading"><div><p class="eyebrow">ORGANIZATION</p><h1>Settings & members</h1><p>Control your company profile, visibility and team access.</p></div></div><div v-if="error" class="form-error">{{error}}</div><div class="settings-grid"><form class="panel settings-form" @submit.prevent="save"><h3>Company profile</h3><label>Name<input v-model="organization.name" required/></label><label>Type<input v-model="organization.type" required/></label><label>Country<input v-model="organization.country" required/></label><label class="check"><input v-model="organization.marketplaceVisible" type="checkbox"/>Visible in company network</label><div v-if="saved" class="success-message">{{saved}}</div><button class="primary">Save settings</button></form><article class="panel table-panel"><div class="table-tools"><div><h3>Members</h3><p class="muted">Role-based access for your team</p></div><button class="primary" @click="showAdd=true"><Plus :size="16"/>Add member</button></div><div class="table-wrap"><table><thead><tr><th>Member</th><th>Role</th><th>Joined</th><th></th></tr></thead><tbody><tr v-for="m in members" :key="m.id"><td><strong>{{m.user.fullName}}</strong><small>{{m.user.email}}</small></td><td><select v-model="m.role" :disabled="m.role==='OWNER'" @change="role(m)"><option>OWNER</option><option>ADMIN</option><option>INVENTORY_MANAGER</option><option>PROCUREMENT_MANAGER</option><option>EMPLOYEE</option><option>VIEWER</option></select></td><td>{{new Date(m.createdAt).toLocaleDateString()}}</td><td><button v-if="m.role!=='OWNER'" class="icon-button danger" @click="remove(m)"><Trash2 :size="16"/></button></td></tr></tbody></table></div></article></div><div v-if="showAdd" class="modal-backdrop" @click.self="showAdd=false"><form class="modal" @submit.prevent="add"><h2>Add member</h2><label>Full name<input v-model="invite.fullName" required/></label><label>Email<input v-model="invite.email" type="email" required/></label><label>Role<select v-model="invite.role"><option>ADMIN</option><option>INVENTORY_MANAGER</option><option>PROCUREMENT_MANAGER</option><option>EMPLOYEE</option><option>VIEWER</option></select></label><div class="modal-actions"><button type="button" class="secondary" @click="showAdd=false">Cancel</button><button class="primary">Add member</button></div></form></div></template>
